/* Local sample knowledge base. File extraction is a reviewed simulation. */
const propertyFields=[
 {id:'name',label:['Property name','民宿名称'],section:'property',value:'Garden House'},
 {id:'location',label:['Location','位置'],section:'property',value:['Lakeside village · Sample location','湖畔村落 · 示例位置']},
 {id:'rooms',label:['Number of rooms','客房数量'],section:'property',type:'number',value:'10'},
 {id:'checkin',label:['Check-in','入住时间'],section:'property',type:'time',value:'14:00'},
 {id:'checkout',label:['Check-out','退房时间'],section:'property',type:'time',value:'11:00'},
 {id:'breakfast',label:['Breakfast','早餐'],section:'facilities',type:'hours',value:'07:00–10:00'},
 {id:'parking',label:['Parking','停车'],section:'facilities',value:''},
 {id:'wifi',label:['Wi-Fi','无线网络'],section:'facilities',value:''},
 {id:'pets',label:['Pets','宠物政策'],section:'facilities',value:''},
 {id:'rules',label:['House rules','入住守则'],section:'guest',type:'long',value:''},
 {id:'arrival',label:['Arrival instructions','抵达指引'],section:'guest',type:'long',value:''},
 {id:'faq',label:['Common questions','常见问题'],section:'guest',type:'long',value:''},
 {id:'style',label:['Style','风格'],section:'about',value:['Quiet garden retreat','安静的花园小住']},
 {id:'features',label:['Features','特色'],section:'about',type:'long',value:['Courtyard, reading nook and a shared dining room.','庭院、阅读角与公共餐厅。']},
 {id:'attractions',label:['Nearby attractions','周边景点'],section:'about',type:'long',value:['Lakeside trail · Village cafés (sample)','湖畔步道、村落咖啡馆（示例）']}
];
const propertyState={values:Object.fromEntries(propertyFields.map(f=>[f.id,f.value])),sources:{},activity:[],files:[],saved:null};
const propertyText=v=>Array.isArray(v)?tx(v):String(v??'');
const propertyValue=id=>propertyText(propertyState.values[id]);
const propertyField=id=>propertyFields.find(f=>f.id===id);
const propertyActivities=()=>propertyState.activity;
let propertyEdit=null,propertyUpload=null,propertyProcessTimer=null;
function propertyDisplay(id){return propertyValue(id)||tr('Not added yet','尚未添加');}
function renderProperty(){document.getElementById('app').innerHTML=`<div class="property-page"><header class="property-top"><span class="sample-label">${tr('MY HOMESTAY','我的民宿')}</span><button id="property-language">${tr('中文','EN')}</button></header><img class="property-photo" src="property-photo.png" alt="${tr('Illustrative garden guesthouse','示例花园民宿')}" width="600" height="400"><p class="property-photo-note">${tr('Illustrative property image','示例民宿图片')}</p><h1>${escapeHtml(propertyValue('name'))}</h1><p class="property-location">${escapeHtml(propertyValue('location'))}</p><p class="property-intro">${tr('The details your AI works from. Keep them clear, current and yours.','这是 AI 工作时参考的民宿资料，由你维护与确认。')}</p>${[['property','Property','民宿资料'],['facilities','Facilities & services','设施与服务'],['guest','Guest information','客人须知'],['about','About the property','关于民宿']].map(([key,en,zh])=>`<section class="property-section"><h2>${tr(en,zh)}</h2>${propertyFields.filter(f=>f.section===key).map(propertyRow).join('')}</section>`).join('')}<section class="property-section"><h2>${tr('Your files','资料文件')}</h2>${propertyState.files.length?propertyState.files.map((f,i)=>`<button class="property-file" data-file="${i}"><span>${escapeHtml(f.name)}<small>${tr('Sample extraction reviewed','已审核示例提取结果')} · ${f.applied} ${tr('details saved','项已保存')}</small></span>${svg('content')}</button>`).join(''):`<p class="property-intro">${tr('Bring in a file, then review what belongs here.','导入文件，确认哪些内容应加入民宿资料。')}</p>`}<button class="property-link" id="property-add-file">${tr('Add a file','添加文件')} ${svg('arrow')}</button></section><p class="property-footer">${tr('Sample knowledge base · Changes stay in this preview until refresh. No connected platforms.','示例知识库 · 修改在本次预览中保留，刷新后重置。未连接外部平台。')}</p><button class="property-ask" id="property-ask"><span aria-hidden="true">✦</span> ${tr('Ask AI','问问 AI')}</button></div>`;
 document.getElementById('property-language').onclick=()=>{lang=lang==='en'?'zh':'en';propertyEdit=null;render()};document.querySelectorAll('[data-property-edit]').forEach(b=>b.onclick=()=>togglePropertyEditor(b.dataset.propertyEdit));document.getElementById('property-ask').onclick=()=>openPropertyAssistant();document.getElementById('property-add-file').onclick=()=>openPropertyAssistant('upload');document.querySelectorAll('[data-file]').forEach(b=>b.onclick=()=>openPropertyAssistant('summary'));const field=location.hash.split('/')[1];if(field&&propertyField(field))togglePropertyEditor(field);
}
function propertyRow(f){return `<div class="property-row" id="property-row-${f.id}"><button class="property-row-toggle" data-property-edit="${f.id}" aria-expanded="false" aria-controls="property-editor-${f.id}"><span class="property-row-label">${tx(f.label)}</span><span class="property-row-value">${escapeHtml(propertyDisplay(f.id))}${propertyState.saved===f.id?`<span class="property-saved" role="status">✓ ${tr('Saved','已保存')}</span>`:''}</span>${svg('right')}</button><div class="property-editor" id="property-editor-${f.id}" inert><div></div></div></div>`;}
function togglePropertyEditor(id){const previous=propertyEdit;if(previous){const box=document.getElementById('property-editor-'+previous);box?.classList.remove('open');if(box)box.inert=true;document.querySelector(`[data-property-edit="${previous}"]`)?.setAttribute('aria-expanded','false')}propertyEdit=null;if(previous===id)return;propertyEdit=id;const f=propertyField(id),box=document.getElementById('property-editor-'+id);box.inert=false;box.querySelector('div').innerHTML=`<form class="property-edit-form"><label for="property-input-${id}">${tr('Edit','编辑')} ${tx(f.label)}</label>${f.type==='hours'?`<div class="property-times"><label>${tr('From','开始')}<input id="property-input-${id}" name="start" type="time" required></label><label>${tr('Until','结束')}<input name="end" type="time" aria-label="${tr('Breakfast end time','早餐结束时间')}" required></label></div>`:f.type==='long'?`<textarea id="property-input-${id}" maxlength="600" required></textarea>`:`<input id="property-input-${id}" type="${f.type||'text'}" ${f.type==='number'?'min="1" max="1000" step="1"':''} maxlength="200" required>`}<p class="property-error" id="property-error-${id}" role="alert"></p><p class="property-source">${tr('Source','资料来源')}: ${escapeHtml(propertyText(propertyState.sources[id]||['Sample property record','示例民宿记录']))}</p><div class="property-actions"><button type="submit">${tr('Save','保存')}</button><button type="button" class="property-cancel">${tr('Cancel','取消')}</button></div></form>`;const form=box.querySelector('form'),input=form.querySelector('input,textarea');if(f.type==='hours'){const [start,end]=propertyValue(id).split('–');form.elements.start.value=start;form.elements.end.value=end}else input.value=propertyValue(id);input.setAttribute('aria-describedby','property-error-'+id);const validate=()=>{let err='';if(f.type==='hours'&&form.elements.start.value>=form.elements.end.value)err=tr('End time must be later than start time.','结束时间必须晚于开始时间。');else if(!input.value.trim())err=tr('Please enter a value.','请输入内容。');input.setCustomValidity(err);form.querySelector('.property-error').textContent=err;return !err};input.onblur=validate;form.oninput=()=>{input.setCustomValidity('');form.querySelector('.property-error').textContent=''};form.onsubmit=e=>{e.preventDefault();if(!validate()||!form.reportValidity())return;const value=f.type==='hours'?form.elements.start.value+'–'+form.elements.end.value:input.value.trim();savePropertyValues([{id,value}],['Edited by you','由你编辑']);propertyState.saved=id;propertyEdit=null;history.replaceState(null,'','#profile');render();document.querySelector(`[data-property-edit="${id}"]`)?.focus({preventScroll:true});announce(tr('Saved to My Homestay.','已保存至我的民宿。'))};form.querySelector('.property-cancel').onclick=()=>{togglePropertyEditor(id);document.querySelector(`[data-property-edit="${id}"]`).focus({preventScroll:true})};box.classList.add('open');document.querySelector(`[data-property-edit="${id}"]`).setAttribute('aria-expanded','true');input.focus({preventScroll:true});}
function savePropertyValues(changes,source){for(const {id,value} of changes){const old=propertyValue(id),next=propertyText(value);if(old===next)continue;propertyState.values[id]=value;propertyState.sources[id]=source;const f=propertyField(id),time=new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});propertyState.activity.unshift({id:'property-'+Date.now()+'-'+id,time,title:['Property information updated','民宿资料已更新'],sub:[f.label[0]+' · '+(old||'Not added')+' → '+next,f.label[1]+' · '+(old||'未添加')+' → '+next],field:id,previous:old,next,source});}}
function propertySheetFrame(title){clearTimeout(propertyProcessTimer);sheet.classList.add('property-sheet');sheet.innerHTML=`<div class="sheet-close-row"><span class="sample-label">${tr('MY HOMESTAY · DEMO','我的民宿 · 演示')}</span><button class="round" id="property-sheet-close" aria-label="${tr('Close','关闭')}">×</button></div><h2 id="activity-title">${title}</h2><div id="property-sheet-body"></div>`;sheet.querySelector('#property-sheet-close').onclick=()=>sheet.close();if(!sheet.open)sheet.showModal();sheet.scrollTop=0;return sheet.querySelector('#property-sheet-body');}
sheet.addEventListener('close',()=>{clearTimeout(propertyProcessTimer);sheet.classList.remove('property-sheet')});
function openPropertyAssistant(mode='main'){const body=propertySheetFrame(tr('A little help with your place.','帮你整理这间民宿。'));if(mode==='upload'){renderPropertyUpload(body);return}if(mode==='summary'){body.innerHTML=`<p>${propertyState.files.length?tr('Your reviewed sample files','已审核的示例文件'):tr('No files have been reviewed yet.','还没有审核过文件。')}</p>${propertyState.files.map(f=>`<blockquote><strong>${escapeHtml(f.name)}</strong><p>${tr(`${f.applied} details were saved after your review.`,`${f.applied} 项资料经你确认后保存。`)}</p><p class="property-sheet-note">${f.changes.map(c=>escapeHtml(tx(propertyField(c.id).label))+': '+escapeHtml(propertyText(c.value))).join('<br>')||tr('You kept the existing information.','你保留了现有资料。')}</p></blockquote>`).join('')}<p class="property-sheet-note">${tr('Summaries describe the fixed demo extraction, not the contents of uploaded files.','摘要仅描述固定的演示提取结果，并非对上传文件的真实解析。')}</p><button class="property-link" id="summary-upload">${tr('Upload a file','上传文件')} ${svg('arrow')}</button>`;body.querySelector('button').onclick=()=>openPropertyAssistant('upload');return}
body.innerHTML=`<p class="property-sheet-note">${tr('Answers use the information you have saved here. File processing and answers are simulated.','回答参考这里已保存的资料。文件处理与回答均为演示。')}</p><div class="property-sheet-actions"><button data-pa="upload">${tr('Upload a file','上传文件')}</button><button data-pa="update">${tr('Update property info','更新民宿资料')}</button><button data-pa="summary">${tr('Summarize my files','总结我的文件')}</button><button data-pa="ask">${tr('Ask about my homestay','询问民宿信息')}</button></div><button class="property-link" id="checkout-question">${tr('What time is check-out?','几点退房？')}</button><form class="property-ask-form"><label class="visually-hidden" for="property-question">${tr('Ask about your property','询问民宿资料')}</label><input id="property-question" placeholder="${tr('Ask about your homestay…','询问民宿资料…')}" maxlength="300" required><button aria-label="${tr('Ask','提问')}">${svg('arrow')}</button></form><div id="property-answer" aria-live="polite"></div>`;body.querySelectorAll('[data-pa]').forEach(b=>b.onclick=()=>{const k=b.dataset.pa;if(k==='update'){body.querySelector('#property-answer').innerHTML=`<div class="property-answer"><p>${tr('Choose the information to update','选择要更新的资料')}</p>${['breakfast','checkout','location','rules'].map(id=>`<button data-edit-source="${id}">${tx(propertyField(id).label)} ${svg('arrow')}</button>`).join('')}</div>`;bindPropertySourceLinks(body)}else if(k==='ask')body.querySelector('input').focus();else openPropertyAssistant(k)});body.querySelector('#checkout-question').onclick=()=>answerPropertyQuestion(tr('What time is check-out?','几点退房？'));body.querySelector('form').onsubmit=e=>{e.preventDefault();const input=body.querySelector('input');if(input.value.trim())answerPropertyQuestion(input.value.trim());else{input.setCustomValidity(tr('Enter a question.','请输入问题。'));input.reportValidity();input.oninput=()=>input.setCustomValidity('')}};}
function answerPropertyQuestion(q){const id=/check.?out|退房/i.test(q)?'checkout':/breakfast|早餐/i.test(q)?'breakfast':/check.?in|入住时间/i.test(q)?'checkin':/wifi|wi-fi|网络/i.test(q)?'wifi':/parking|停车/i.test(q)?'parking':/pets|宠物/i.test(q)?'pets':/location|地址|位置/i.test(q)?'location':null;const box=sheet.querySelector('#property-answer');let answer=tr('Try asking about check-out, breakfast, parking or Wi-Fi. This demo only reads saved property fields.','可以问退房、早餐、停车或 Wi-Fi。演示仅查询已保存的资料。');if(id){let v=propertyValue(id);if(id==='checkout'&&lang==='en'&&v){const [h,m]=v.split(':').map(Number);v=`${h%12||12}:${String(m).padStart(2,'0')} ${h<12?'AM':'PM'}`}answer=v?(id==='checkout'?tr(`Your current check-out time is ${v}.`,`当前退房时间为 ${v}。`):tx(propertyField(id).label)+': '+v):tr('This detail has not been added yet.','这项资料尚未添加。')};box.innerHTML=`<div class="property-answer"><small>${escapeHtml(q)}</small><p>${escapeHtml(answer)}</p>${id?`<small>${tr('From My Homestay → ','来源：我的民宿 → ')}${propertyField(id).section==='property'?tr('Property details','民宿资料'):tr('Facilities & services','设施与服务')}</small><button data-edit-source="${id}">${tr('Edit this information','编辑这项资料')} ${svg('arrow')}</button>`:''}</div>`;bindPropertySourceLinks(box);box.scrollIntoView({behavior:motion()?'smooth':'instant',block:'nearest'});}
function bindPropertySourceLinks(root){root.querySelectorAll('[data-edit-source]').forEach(b=>b.onclick=()=>{sheet.close();const id=b.dataset.editSource;if(page==='profile'){propertyEdit=null;togglePropertyEditor(id);document.getElementById('property-row-'+id).scrollIntoView({behavior:motion()?'smooth':'instant',block:'center'})}else location.hash='profile/'+id})}
const propertyExtraction=[{id:'breakfast',value:'07:30–10:00'},{id:'checkout',value:'11:30'},{id:'parking',value:['Free courtyard parking · 4 spaces','免费庭院停车 · 4 个车位']},{id:'wifi',value:['Free Wi-Fi in rooms and shared areas','客房与公共区域提供免费 Wi-Fi']},{id:'pets',value:['Pets by prior agreement','宠物入住需提前确认']},{id:'rules',value:['No smoking indoors. Quiet hours 22:00–08:00.','室内禁烟。安静时段为 22:00–08:00。']},{id:'arrival',value:['Enter through the garden gate; reception is on the left.','从花园大门进入，接待处在左侧。']},{id:'faq',value:['Luggage can be stored before check-in.','入住前可寄存行李。']}];
function renderPropertyUpload(body){body.innerHTML=`<p>${tr('Turn a file into useful property details.','把文件整理为可用的民宿资料。')}</p><p class="property-sheet-note">${tr('Demo: use property-info.pdf below, or choose a PDF to try the same sample workflow. File contents are not read or uploaded.','演示：使用下方 property-info.pdf，或选择 PDF 体验相同的示例流程。不会读取或上传文件内容。')}</p><button class="confirm-task" id="sample-upload">${tr('Try property-info.pdf','试用 property-info.pdf')} ${svg('arrow')}</button><label class="file-pick">${tr('Or choose a PDF · Max 10 MB','或选择 PDF · 最大 10 MB')}<input id="property-file-input" type="file" accept=".pdf,application/pdf"></label><p id="property-upload-error" class="property-error" role="alert"></p>`;body.querySelector('#sample-upload').onclick=()=>processPropertyFile('property-info.pdf');body.querySelector('input').onchange=e=>{const f=e.target.files[0];if(!f)return;const error=body.querySelector('#property-upload-error');if(!/\.pdf$/i.test(f.name)||f.size>10*1024*1024){error.textContent=tr('Choose a PDF no larger than 10 MB.','请选择不超过 10 MB 的 PDF。');e.target.value='';return;}processPropertyFile(f.name)};}
function processPropertyFile(name){const body=propertySheetFrame(tr('Reading the sample…','正在整理示例…'));body.innerHTML=`<div class="property-processing" role="status"><div class="quiet-dots" aria-hidden="true"><i></i><i></i><i></i></div><strong>${escapeHtml(name)}</strong><p>${tr('Simulating extraction. No property information has changed.','正在模拟提取，民宿资料尚未改变。')}</p></div>`;propertyUpload={name,items:propertyExtraction.map(x=>({...x,current:propertyState.values[x.id],choice:null}))};propertyProcessTimer=setTimeout(()=>{if(sheet.open)renderPropertyReview()},motion()?850:0);}
function renderPropertyReview(){const body=propertySheetFrame(tr('I found 8 property details.','发现 8 项民宿资料。'));const fresh=propertyUpload.items.filter(x=>!propertyText(x.current)).length;body.innerHTML=`<p>${tr(`${fresh} new details · ${8-fresh} possible updates`,`${fresh} 项新资料 · ${8-fresh} 项可能更新`)}</p><p class="property-sheet-note">${escapeHtml(propertyUpload.name)} · ${tr('Fixed sample extraction. Review every item before saving.','固定示例提取结果，请逐项确认后保存。')}</p>${propertyUpload.items.map(x=>{const exists=!!propertyText(x.current);return `<article class="upload-review"><h3>${tx(propertyField(x.id).label)}</h3><dl><div><dt>${tr('Current','当前')}</dt><dd>${escapeHtml(propertyText(x.current)||tr('Not added','未添加'))}</dd></div><div><dt>${tr('From file · Demo','文件提取 · 示例')}</dt><dd>${escapeHtml(propertyText(x.value))}</dd></div></dl><div class="upload-decisions"><button data-choice="keep" data-key="${x.id}" aria-pressed="${x.choice==='keep'}">${exists?tr('Keep current','保留当前'):tr('Skip','跳过')}</button><button data-choice="update" data-key="${x.id}" aria-pressed="${x.choice==='update'}">${exists?tr('Update','更新'):tr('Add','添加')}</button></div></article>`}).join('')}<div class="upload-apply"><p class="upload-status" id="upload-status" role="status"></p><button class="confirm-task" id="apply-property-file" disabled>${tr('Confirm & save choices','确认并保存选择')} ${svg('arrow')}</button></div>`;body.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{const item=propertyUpload.items.find(x=>x.id===b.dataset.key);item.choice=b.dataset.choice;body.querySelectorAll(`[data-key="${item.id}"]`).forEach(btn=>btn.setAttribute('aria-pressed',String(btn.dataset.choice===item.choice)));updatePropertyReviewStatus()});body.querySelector('#apply-property-file').onclick=applyPropertyFile;updatePropertyReviewStatus();}
function updatePropertyReviewStatus(){const n=propertyUpload.items.filter(x=>x.choice).length;document.getElementById('upload-status').textContent=tr(`${n} of 8 reviewed · Nothing saved yet`,`${n} / 8 已确认 · 尚未保存`);document.getElementById('apply-property-file').disabled=n!==8;}
function applyPropertyFile(){if(propertyUpload.items.some(x=>!x.choice))return;const changes=propertyUpload.items.filter(x=>x.choice==='update'&&propertyText(x.value)!==propertyValue(x.id));savePropertyValues(changes,[propertyUpload.name+' · Reviewed sample',propertyUpload.name+' · 已审核示例']);propertyState.files.push({name:propertyUpload.name,applied:changes.length,changes:changes.map(x=>({id:x.id,value:x.value}))});const body=propertySheetFrame(tr('Your knowledge base is up to date.','民宿知识库已更新。'));body.innerHTML=`<p role="status">✓ ${tr(`${changes.length} details saved after your confirmation.`,`${changes.length} 项资料经你确认后保存。`)}</p><p class="property-sheet-note">${tr('Your decisions are recorded in Work. No external platforms were updated.','修改已记录到工作区，未更新外部平台。')}</p><button class="confirm-task" id="file-done">${tr('Back to My Homestay','返回我的民宿')} ${svg('arrow')}</button><button class="property-link" id="file-activity">${tr('View activity in Work','查看工作区记录')} ${svg('arrow')}</button>`;propertyEdit=null;if(page==='profile')render();body.querySelector('#file-done').onclick=()=>sheet.close();body.querySelector('#file-activity').onclick=()=>{sheet.close();goPage('work')};}
const originalPropertyActivity=showActivity;
showActivity=function(id){const item=propertyState.activity.find(x=>x.id===id);if(!item){originalPropertyActivity(id);if(id==='breakfast'){sheet.querySelector('#view-property').onclick=()=>{sheet.close();goPage('profile')}}return;}const body=propertySheetFrame(tx(propertyField(item.field).label)+' · '+tr('Updated','已更新'));body.innerHTML=`<div class="change-comparison"><div><span>${tr('Previous','之前')}</span><p>${escapeHtml(item.previous||tr('Not added','未添加'))}</p></div><div><span>${tr('New','现在')}</span><p>${escapeHtml(item.next)}</p></div></div><p class="property-sheet-note">${escapeHtml(propertyText(item.source))}</p><p>${tr('Saved to My Homestay','已保存至我的民宿')}</p><button class="confirm-task" data-edit-source="${item.field}">${tr('View property','查看民宿')} ${svg('arrow')}</button>`;bindPropertySourceLinks(body)};
const archivedBreakfastIndex=baseActivity.findIndex(x=>x.id==='breakfast');
if(archivedBreakfastIndex>=0)baseActivity.splice(archivedBreakfastIndex,1);
const renderWithProperty=render;
render=function(){if(page==='profile')propertyEdit=null;renderWithProperty();if(page==='home'){const old=document.querySelector('[data-activity="breakfast"]');if(old){const latest=propertyState.activity[0];if(latest){old.dataset.activity=latest.id;old.textContent='✓ '+tx(latest.title);old.onclick=()=>showActivity(latest.id)}else{old.removeAttribute('data-activity');old.textContent=tr('Keep your property information up to date →','完善你的民宿资料 →');old.onclick=()=>goPage('profile')}}}};
render();
